python3 -c "
import json
with open('/home/ubuntu/.agent-ml-research-idea_gen_0509_6/projects/schema_semantic_constrained_ie/logs/workers/worker_fix_llama_bootstrap_v2_retry_20260514T224559.log') as f:
    lines = f.readlines()
for i, line in enumerate(lines):
    line = line.strip()
    if not line:
        continue
    try:
        entry = json.loads(line)
    except:
        print(f'L{i+1}: PARSE ERROR (len={len(line)})')
        continue
    if entry.get('type') == 'assistant':
        msg = entry.get('message', {})
        content = msg.get('content', [])
        stop = msg.get('stop_reason','')
        for c in content:
            if isinstance(c, dict):
                if c.get('type') == 'tool_use':
                    name = c.get('name','')
                    if name == 'TaskOutput':
                        print(f'L{i+1}: TaskOutput')
                    elif 'ssh' in name:
                        cmd = c.get('input',{}).get('command','')[:150]
                        print(f'L{i+1}: {name} → {cmd}')
                    else:
                        print(f'L{i+1}: {name}')
                elif c.get('type') == 'text':
                    txt = c.get('text','')[:150]
                    if txt.strip():
                        print(f'L{i+1}: TEXT: {txt}')
        if stop:
            print(f'  (stop_reason={stop})')
